    98→export function HabitCard({
    99→  id,
   100→  name,
   101→  icon = '📝',
   102→  color,
   103→  strength,
   104→  currentStreak = 0,
   105→  bestStreak = 0,
   106→  completed: completedProp = false,
   107→  atRisk = false,
   108→  disabled = false,
   109→  onPress,
   110→  onLongPress,
   111→  onEdit,
   112→  onDelete,
