   114→}: HabitCardProps) {
   115→  const theme = useAppTheme();
   116→  const translateX = useSharedValue(0);
   117→  const cardScale = useSharedValue(1);
   118→
   119→  // Strength fill animation - fills card background based on habit strength percentage
   120→  const strengthFillWidth = useSharedValue(strength);
   121→
   122→  // Enhanced animation values for completion
   123→  const checkmarkScale = useSharedValue(0);
   124→  const checkmarkRotate = useSharedValue(0);
   125→  const rippleScale = useSharedValue(0);
   126→  const rippleOpacity = useSharedValue(0);
   127→
   128→  // Floating XP text state
   129→  const [showFloatingXP, setShowFloatingXP] = React.useState(false);
   130→  const [xpPosition, setXPPosition] = React.useState({ x: 0, y: 0 });
   131→
   132→  // Prevent rapid-fire toggles with debounce flag
   133→  const [isToggling, setIsToggling] = React.useState(false);
   134→
   135→  // Get today's date in YYYY-MM-DD format
   136→  const today = new Date().toISOString().split('T')[0];
   137→
   138→  // Query current completion status for conditional haptic feedback
   139→  // Returns true if completed, false if not completed, undefined while loading
   140→  const completedQuery = useQuery(api.tracking.getCompletionStatus, {
   141→    date: today,
   142→    habitId: id,
   143→  });
   144→  const completed = completedQuery ?? completedProp;
   145→
   146→  // Animate strength fill when strength changes
   147→  useEffect(() => {
   148→    strengthFillWidth.value = withSpring(strength, {
   149→      damping: 15,
   150→      stiffness: 100,
   151→    });
   152→  }, [strength]);
   153→
   154→  // Sync checkmark animation with query result
   155→  useEffect(() => {
   156→    if (completed) {
   157→      // Show checkmark without animation (already completed)
   158→      checkmarkScale.value = 1;
   159→      checkmarkRotate.value = 360;
   160→    } else {
   161→      // Hide checkmark without animation (not completed)
   162→      checkmarkScale.value = 0;
   163→      checkmarkRotate.value = 0;
   164→    }
   165→  }, [completed]);
   166→
   167→  // Get strength color based on current level
   168→  const getStrengthColor = (): string => {
   169→    const level = getStrengthLevel(strength);
   170→    switch (level) {
   171→      case 'starting':
   172→        return theme.custom.colors.strength.starting;
   173→      case 'building':
   174→        return theme.custom.colors.strength.building;
   175→      case 'developing':
   176→        return theme.custom.colors.strength.developing;
   177→      case 'strong':
   178→        return theme.custom.colors.strength.strong;
   179→      case 'automatic':
   180→        return theme.custom.colors.strength.automatic;
   181→      default:
   182→        return theme.custom.colors.primary[500];
   183→    }
   184→  };
   185→
   186→  // Get strength level emoji for visual reinforcement
   187→  const getStrengthEmoji = (): string => {
   188→    const level = getStrengthLevel(strength);
   189→    switch (level) {
   190→      case 'starting':
   191→        return '🌱';
   192→      case 'building':
   193→        return '🌿';
   194→      case 'developing':
   195→        return '🌳';
   196→      case 'strong':
   197→        return '💪';
   198→      case 'automatic':
   199→        return '⚡';
   200→      default:
   201→        return '🌱';
   202→    }
   203→  };
   204→
   205→  // Convex mutation for toggling completion
   206→  const toggleCompletionMutation = useMutation(api.tracking.toggleCompletion);
   207→
   208→  // Note: Haptic feedback will be called inline with runOnJS wrapper
   209→  // This pattern is required for Reanimated worklets
   210→
   211→  // ========================================
   212→  // ENHANCED COMPLETION ANIMATION (Part B: Micro-Transitions)
   213→  // Using Springs.bouncy for playful celebration animations
   214→  // ========================================
   215→  const triggerCompletionCelebration = () => {
   216→    'worklet';
   217→
   218→    // Phase 1: Card bounce (100-400ms)
   219→    cardScale.value = withSequence(
   220→      withSpring(1.05, Springs.bouncy),
   221→      withSpring(1.0, Springs.button)
   222→    );
   223→
   224→    // Phase 2: Checkmark animation (0-400ms)
   225→    // Scale: 0 → 1.2 → 1.0 (elastic spring)
   226→    // Using Springs.bouncy for the playful entrance
   227→    checkmarkScale.value = withSequence(
   228→      withSpring(1.2, Springs.bouncy),
   229→      withSpring(1.0, Springs.button)
   230→    );
   231→
   232→    // Rotation: 0 → 360deg
   233→    checkmarkRotate.value = withTiming(360, {
   234→      duration: 400,
   235→      easing: Easing.out(Easing.cubic),
   236→    });
   237→
   238→    // Phase 3: Ripple effect (100-500ms)
   239→    rippleScale.value = 0;
   240→    rippleOpacity.value = 0.3;
   241→
   242→    rippleScale.value = withTiming(2, {
   243→      duration: 500,
   244→      easing: Easing.out(Easing.cubic),
   245→    });
   246→
   247→    rippleOpacity.value = withTiming(0, {
   248→      duration: 500,
   249→      easing: Easing.out(Easing.cubic),
   250→    });
   251→
   252→    // Phase 4: Trigger floating XP text
   253→    runOnJS(setShowFloatingXP)(true);
   254→    runOnJS(() => {
   255→      // Calculate position (center of card)
   256→      setXPPosition({ x: 150, y: 20 });
   257→
   258→      // Hide after animation completes
   259→      setTimeout(() => setShowFloatingXP(false), 1000);
   260→    })();
   261→  };
   262→
   263→  const triggerUncheckAnimation = () => {
   264→    'worklet';
   265→
   266→    // Simple fade out for checkmark
   267→    checkmarkScale.value = withTiming(0, {
   268→      duration: 200,
   269→      easing: Easing.in(Easing.cubic),
   270→    });
   271→
   272→    checkmarkRotate.value = 0;
   273→  };
