    14→/**
    15→ * StreakChain renders a compact chain visualization similar to the provided design.
    16→ * - Left: label (e.g., "Reading Chain")
    17→ * - Right: rounded pill with streak days
    18→ * - Below: row of circles with link icon, connected by short bars
    19→ *
    20→ * Design language:
    21→ * - Typography and colors align with existing app styles (#1c1917 titles, #78716c secondary, #e7e5e4 borders)
    22→ * - Primary color uses #3B82F6 (blue)
    23→ */
    24→export default function StreakChain({
    25→  label,
    26→  statuses,
    27→  size = 28,
    28→}: StreakChainProps) {
    29→  const { circleSize, iconSize, streakDays } = useStreakChainLogic(
    30→    statuses,
    31→    size
    32→  );
    33→
    34→  return (
    35→    <View className='pb-3 pt-1'>
    36→      <View className='mb-2 flex-row items-center justify-between'>
    37→        <Text className='text-base font-bold tracking-tight text-stone-900'>
    38→          {label}
    39→        </Text>
    40→        <View
    41→          accessibilityLabel={`${streakDays} days`}
    42→          className='rounded-full bg-indigo-50 px-2.5 py-1'
