    46→          </Text>
    47→        </View>
    48→      </View>
    49→
    50→      <View className='flex-row items-center'>
    51→        {statuses.map((status, idx) => {
    52→          const isDone = status === 'done';
    53→          const isFuture = status === 'planned'; // treat planned as future/disabled
    54→          const connectorActive = idx < statuses.length - 1 && isDone;
    55→
    56→          return (
    57→            <View key={idx} className='flex-row items-center'>
    58→              <View
    59→                className='items-center justify-center'
    60→                style={{
    61→                  backgroundColor: isDone ? '#3B82F6' : '#E5E7EB',
    62→                  borderRadius: circleSize / 2,
    63→                  height: circleSize,
    64→                  opacity: isFuture ? 0.5 : 1,
    65→                  width: circleSize,
    66→                }}
    67→              >
    68→                <Feather
    69→                  color={isDone ? '#FFFFFF' : '#64748B'}
    70→                  name='link-2'
    71→                  size={iconSize}
    72→                />
    73→              </View>
    74→
    75→              {idx < statuses.length - 1 && (
    76→                <View
    77→                  className='mx-1.5 h-0.5 w-[18px] rounded-sm'
    78→                  style={{
    79→                    backgroundColor: connectorActive ? '#93C5FD' : '#E5E7EB',
    80→                  }}
    81→                />
    82→              )}
    83→            </View>
    84→          );
    85→        })}
    86→      </View>
    87→    </View>
    88→  );
